import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`call-coaching`,heroTitle:`Coach every sales call in minutes`,heroSubtitle:`Perplexity Computer reviews your call recordings, scores rep performance, and delivers personalized coaching plans - automatically.`,hasInputUrl:!1,heroOverlaySteps:[`Analyzing call recordings for talk patterns and objection handling`,`Scoring each rep against top-performer benchmarks`,`Building personalized coaching plans with specific talk tracks`,`Rep scorecards, skill gaps, and coaching playbooks - ready to review`],generatingSteps:[`Preparing to ingest your sales call recordings and CRM deal data`,`Designing an agent to score talk-to-listen ratio, objection handling, and discovery quality`,`Configuring benchmark comparisons against your top closers' patterns`,`Setting up personalized coaching plans and weekly performance reports`],featureSectionTitle:`From call recordings to coaching playbooks`,featureCardTitles:[`Connects to your sales stack`,`Outputs you can coach from`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Drive, Slack, Google Sheets, Notion, Pipedrive - Computer plugs into your tools so call insights flow straight into coaching workflows and team channels.`,`Rep scorecards with skill breakdowns. Objection-handling heat maps. Talk track recommendations. Personalized coaching plans tied to real call moments.`],capabilitySectionTitle:`Your call coach, on autopilot`,capabilitySectionSubtitle:`Upload your calls, step away, come back to actionable coaching for every rep.`,capabilityCards:[{title:`Call Scoring`,description:`Computer can score every call on talk-to-listen ratio, discovery depth, objection handling, next-step setting, and closing technique - benchmarked against your top performers.`},{title:`Skill Gap Analysis`,description:`Computer can identify each rep's weakest areas across dozens of calls - surfacing patterns no manager could catch from spot-checking alone.`},{title:`Coaching Plans`,description:`Computer can generate personalized coaching plans for each rep - with specific talk tracks, drill exercises, and real call clips to review.`},{title:`Connect Your Tools`,description:`Computer can pull from Google Drive, Slack, Pipedrive, Notion, and Google Sheets - building coaching workflows across your entire sales enablement stack.`},{title:`Track Progress`,description:`Computer can remember each rep's scores, coaching history, and improvement trends across sessions - so every review builds on prior feedback.`},{title:`Weekly Alerts`,description:`Computer can monitor rep performance weekly and flag regressions, breakout improvements, or reps who need immediate manager attention.`}]});export{t as default};
